import requests

def check_borders(qid, name):
    url = 'https://query.wikidata.org/sparql'
    query = f"""
    SELECT ?neighborLabel ?countryLabel WHERE {{
      wd:{qid} wdt:P47 ?neighbor.
      ?neighbor wdt:P17 ?country.
      SERVICE wikibase:label {{ bd:serviceParam wikibase:language "en". }}
    }}
    """
    headers = {'Accept': 'application/json', 'User-Agent': 'Mozilla/5.0'}
    r = requests.get(url, params={'query': query}, headers=headers)
    data = r.json()
    print(f"--- {name} ---")
    for item in data['results']['bindings']:
        neighbor = item['neighborLabel']['value']
        country = item['countryLabel']['value']
        if country != 'Switzerland':
            print(f"Borders {neighbor} ({country})")

check_borders('Q11933', 'Solothurn')
check_borders('Q11911', 'Bern')
EOF
